// src/utils/speech.js
import { logger } from './logger';

export function getVoices() {
  return window.speechSynthesis ? window.speechSynthesis.getVoices() : [];
}

export function speak(text, rate = 1, pitch = 1, voiceURI = '') {
  if (!window.speechSynthesis) {
    logger.warn('Speech synthesis not supported');
    return;
  }
  logger.debug(`Speak: "${text}"`, { rate, pitch, voiceURI });
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = 'ru-RU';
  utterance.rate = rate;
  utterance.pitch = pitch;
  if (voiceURI) {
    const voices = getVoices();
    const found = voices.find(v => v.voiceURI === voiceURI);
    if (found) utterance.voice = found;
  }
  window.speechSynthesis.speak(utterance);
}

toast.js.content:
// src/utils/toast.js
import { createElement } from './dom';
import { logger } from './logger';

let container = null;

function getContainer() {
  if (!container) {
    container = createElement('div', { className: 'toast-container' });
    document.body.appendChild(container);
  }
  return container;
}

export function toast(message, type = 'info', duration = 2500) {
  logger.info(`Toast: ${message} (${type})`);
  const el = createElement('div', { className: `toast ${type}` }, message);
  const c = getContainer();
  c.appendChild(el);
  setTimeout(() => {
    el.style.opacity = '0';
    setTimeout(() => el.remove(), 300);
  }, duration);
}

